1	/**
2	 * Shared brief → names → live availability → ranked results pipeline.
3	 *
4	 * BOTH surfaces of the domain-name generator run through here:
5	 *   - the public, SEO marketing tool  (app/api/tools/domain-generator/route.ts)
6	 *   - the signed-in customer portal    (app/api/dashboard/domains/generate/route.ts)
7	 *
8	 * The orchestration lived inline in the public route. A second copy for the
9	 * portal would have been this codebase's single most common defect — two answers
10	 * to "how do we turn a brief into available names", drifting apart. So the whole
11	 * pipeline is one function, `generateSuggestions`, and each route contributes
12	 * only what genuinely differs: how the caller is identified and throttled, and
13	 * whether the visitor is signed in.
14	 *
15	 * Honesty invariants enforced here, not in the UI:
16	 *   - a result is only ever "available" when the REGISTRAR returned a real price
17	 *     for it (that guarantee comes from domain-availability.ts and is preserved
18	 *     verbatim by `toSuggestResult`);
19	 *   - when the registrar can't be reached the name degrades to "unknown"
20	 *     ("couldn't verify"), never to "available";
21	 *   - a price is only carried when the registrar gave one.
22	 *
23	 * The small helpers (`readTlds`, `buildDomains`, `mergeCandidates`,
24	 * `toSuggestResult`, `rankSuggestions`, `partitionResults`) are pure and are
25	 * unit-tested in test/domain-suggest.test.ts.
26	 */
27	
28	import { aiAvailable, aiCandidates } from "./domain-ai";
29	import { checkAvailabilityBatched, type DomainResult } from "./domain-availability";
30	import { generateCandidates, type Candidate } from "./domain-generate";
31	import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "./domain-vocab";
32	
33	/** Distinct name ideas per request. Caps the single Claude call's output. */
34	export const MAX_NAMES = 12;
35	
36	/** Absolute ceiling on registrar lookups per request (names × TLDs). */
37	export const MAX_LOOKUPS = 24;
38	
39	/** TLDs a caller may select at once. */
40	export const MAX_TLDS = 3;
41	
42	export const MAX_IDEA_LEN = 400;
43	export const MAX_KEYWORDS_LEN = 120;
44	
45	/** A brief shorter than this is rejected before any AI or registrar spend. */
46	export const MIN_IDEA_LEN = 8;
47	
48	const VALID_TONES = new Set(TONES.map((t) => t.value));
49	
50	export type SuggestStatus = "available" | "taken" | "unknown";
51	
52	export type SuggestResult = {
53	  domain: string;
54	  sld: string;
55	  tld: string;
56	  status: SuggestStatus;
57	  premium: boolean;
58	  /** Retail first-year price in integer cents, or null when the registrar gave none. */
59	  priceCents: number | null;
60	  /** Retail renewal price in integer cents, or null. */
61	  renewCents: number | null;
62	  style: string;
63	  note: string;
64	};
65	
66	export type SuggestResponse = {
67	  /** "ai" when Claude produced the names, "heuristic" when the fallback did. */
68	  source: "ai" | "heuristic";
69	  /** False when the registrar isn't configured — every result is "unknown". */
70	  registrarConfigured: boolean;
71	  /** True when we skipped some registrar lookups to protect the shared budget. */
72	  throttled: boolean;
73	  checked: number;
74	  tlds: string[];
75	  results: SuggestResult[];
76	};
77	
78	/* ---------------------------------------------------------------------------
79	 * Input normalisation — pure
80	 * ------------------------------------------------------------------------ */
81	
82	/** Collapse whitespace, trim, and hard-cap length. Non-strings become "". */
83	export function readString(v: unknown, max: number): string {
84	  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
85	}
86	
87	export function readIdea(v: unknown): string {
88	  return readString(v, MAX_IDEA_LEN);
89	}
90	
91	export function readKeywords(v: unknown): string {
92	  return readString(v, MAX_KEYWORDS_LEN);
93	}
94	
95	/** Coerce arbitrary input to a known tone, defaulting to "any". */
96	export function readTone(v: unknown): Tone {
97	  const raw = readString(v, 20) as Tone;
98	  return VALID_TONES.has(raw) ? raw : "any";
99	}
100	
101	/**
102	 * Sanitise the requested TLD list: lower-cased, de-dotted, de-duplicated, only
103	 * ones we actually offer, capped at MAX_TLDS. Falls back to the defaults when
104	 * nothing valid survives.
105	 */
106	export function readTlds(v: unknown): string[] {
107	  if (!Array.isArray(v)) return [...DEFAULT_TLDS];
108	  const out: string[] = [];
109	  for (const raw of v) {
110	    if (typeof raw !== "string") continue;
111	    const tld = raw.toLowerCase().replace(/^\./, "").trim();
112	    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
113	    if (out.length >= MAX_TLDS) break;
114	  }
115	  return out.length ? out : [...DEFAULT_TLDS];
116	}
117	
118	/* ---------------------------------------------------------------------------
119	 * Candidate assembly — pure
120	 * ------------------------------------------------------------------------ */
121	
122	/**
123	 * Fill `primary` (the AI names) up to `max` with `fallback` (heuristic names),
124	 * de-duplicating on the bare label. Primary keeps its order and priority; the
125	 * fallback only ever tops up a short or missing AI list.
126	 */
127	export function mergeCandidates(
128	  primary: Candidate[] | null,
129	  fallback: Candidate[],
130	  max: number,
131	): Candidate[] {
132	  const merged = primary ? primary.slice(0, max) : [];
133	  if (merged.length >= max) return merged;
134	  const seen = new Set(merged.map((c) => c.sld));
135	  for (const c of fallback) {
136	    if (merged.length >= max) break;
137	    if (seen.has(c.sld)) continue;
138	    seen.add(c.sld);
139	    merged.push(c);
140	  }
141	  return merged;
142	}
143	
144	/**
145	 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
146	 * caller's first-choice extension is checked for every name before we spend any
147	 * budget on the second choice.
148	 */
149	export function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
150	  const domains: string[] = [];
151	  for (const tld of tlds) {
152	    for (const c of candidates) {
153	      if (domains.length >= MAX_LOOKUPS) return domains;
154	      domains.push(`${c.sld}.${tld}`);
155	    }
156	  }
157	  return domains;
158	}
159	
160	/* ---------------------------------------------------------------------------
161	 * Result shaping — pure
162	 * ------------------------------------------------------------------------ */
163	
164	/**
165	 * Combine a registrar availability result with its candidate's copy. The
166	 * availability status is carried through UNCHANGED — an "unknown" (couldn't
167	 * verify) is never promoted to "available" here, and a price only survives when
168	 * the registrar actually returned one.
169	 */
170	export function toSuggestResult(r: DomainResult, meta?: Pick<Candidate, "style" | "note">): SuggestResult {
171	  const dot = r.domain.lastIndexOf(".");
172	  const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
173	  const tld = dot >= 0 ? r.domain.slice(dot + 1) : "";
174	  return {
175	    domain: r.domain,
176	    sld,
177	    tld,
178	    status: r.status,
179	    premium: r.premium,
180	    priceCents: r.priceCents,
181	    renewCents: r.renewCents,
182	    style: meta?.style ?? "invented",
183	    note: meta?.note ?? "",
184	  };
185	}
186	
187	/** A name we can put a "Register" button on: verified free with a real price. */
188	export function isRegisterable(r: SuggestResult): boolean {
189	  return r.status === "available" && r.priceCents !== null;
190	}
191	
192	/** Available first (cheapest first within that), then unknown, then taken. Mutates + returns. */
193	export function rankSuggestions(results: SuggestResult[]): SuggestResult[] {
194	  const rank: Record<SuggestStatus, number> = { available: 0, unknown: 1, taken: 2 };
195	  results.sort(
196	    (a, b) =>
197	      rank[a.status] - rank[b.status] ||
198	      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
199	      a.domain.length - b.domain.length,
200	  );
201	  return results;
202	}
203	
204	/**
205	 * Split results into the three buckets both UIs render. `available` is the
206	 * differentiator: only genuinely-free, priced names. `unchecked` are the
207	 * "couldn't verify" names; `taken` are confirmed registered.
208	 */
209	export function partitionResults(results: SuggestResult[]): {
210	  available: SuggestResult[];
211	  unchecked: SuggestResult[];
212	  taken: SuggestResult[];
213	} {
214	  return {
215	    available: results.filter((r) => r.status === "available"),
216	    unchecked: results.filter((r) => r.status === "unknown"),
217	    taken: results.filter((r) => r.status === "taken"),
218	  };
219	}
220	
221	/* ---------------------------------------------------------------------------
222	 * The pipeline — the one impure step (AI + registrar)
223	 * ------------------------------------------------------------------------ */
224	
225	export type SuggestInput = {
226	  /** Already normalised + validated (>= MIN_IDEA_LEN) by the caller. */
227	  idea: string;
228	  keywords: string;
229	  tone: Tone;
230	  tlds: string[];
231	};
232	
233	/**
234	 * Names then live availability. Never throws: a missing key falls back to the
235	 * heuristic generator, a registrar failure degrades to "unknown". Returns a
236	 * response body with everything both routes need EXCEPT `signedIn`, which each
237	 * route supplies for itself.
238	 *
239	 * When the brief yields no usable labels at all, `results` is empty and the
240	 * caller should surface a "try more detail" message rather than a page of
241	 * nothing — that is the ONLY time `results` is empty (taken/unknown names still
242	 * produce results).
243	 */
244	export async function generateSuggestions(input: SuggestInput): Promise<SuggestResponse> {
245	  const { idea, keywords, tone, tlds } = input;
246	
247	  // 1) Names — Claude when the platform key is set, heuristics otherwise.
248	  let aiNames: Candidate[] | null = null;
249	  let source: "ai" | "heuristic" = "heuristic";
250	  if (aiAvailable()) {
251	    aiNames = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
252	    if (aiNames && aiNames.length) source = "ai";
253	  }
254	  const needFallback = !aiNames || aiNames.length < MAX_NAMES;
255	  const fallback = needFallback ? generateCandidates({ idea, keywords, tone, limit: MAX_NAMES }) : [];
256	  const candidates = mergeCandidates(aiNames, fallback, MAX_NAMES);
257	
258	  const byLabel = new Map(candidates.map((c) => [c.sld, c]));
259	
260	  // 2) Availability — one batched, cached, globally-throttled registrar call.
261	  const domains = buildDomains(candidates, tlds);
262	  const availability = await checkAvailabilityBatched(domains);
263	
264	  const results = availability.results.map((r: DomainResult) => {
265	    const dot = r.domain.lastIndexOf(".");
266	    const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
267	    return toSuggestResult(r, byLabel.get(sld));
268	  });
269	  rankSuggestions(results);
270	
271	  return {
272	    source,
273	    registrarConfigured: availability.configured,
274	    throttled: availability.throttled,
275	    checked: results.length,
276	    tlds,
277	    results,
278	  };
279	}
