192	// ---------- Inbound transfers (transfer-in) ----------
193	//
194	// name.com v4 transfers:
195	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
196	//   GET  /v4/transfers                      -> { transfers: [...] }
197	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
198	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
199	//
200	// A transfer always includes a 1-year extension of the registration, which is
201	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
202	// registration rate.
203	
204	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
205	const SANDBOX_APPROVAL_MS = 2 * 60_000;
206	const SANDBOX_REGISTRY_MS = 5 * 60_000;
207	
208	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
209	function sandboxTldCostCents(domain: string): number {
210	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
211	  let h = 0;
212	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
213	  return 900 + (h % 21) * 50; // $9.00 – $19.00
214	}
