349	export type TransferInfo = {
350	  domain: string;
351	  /** Raw registrar status, shown to the customer verbatim. */
352	  status: string;
353	  /** Where the losing registrar sent the approval email (not every TLD sends one). */
354	  email: string | null;
355	};
356	
357	/**
358	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
359	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
360	 * The auth code is passed straight through and never logged.
361	 */
362	export async function createTransfer(
363	  domain: string,
364	  authCode: string,
365	  purchaseCents: number
366	): Promise<TransferInfo> {
367	  if (SANDBOX) {
368	    // Names containing "fail" reject at submit time so staging can exercise the
369	    // "registrar refused, customer not charged" path.
370	    if (domain.includes("fail")) throw new Error("name.com: transfer rejected by the registry (sandbox)");
371	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
372	  }
373	  const json = await nc("POST", "/v4/transfers", {
374	    domainName: domain,
375	    authCode,
376	    privacyEnabled: true,
377	    purchasePrice: purchaseCents / 100,
378	  });
379	  const t = json?.transfer ?? json ?? {};
380	  return {
381	    domain: t.domainName ?? domain,
382	    status: String(t.status ?? "pending"),
383	    email: t.email ? String(t.email) : null,
384	  };
385	}
386	
387	/**
388	 * Current state of an inbound transfer. Returns null when the registrar has no
389	 * transfer for this domain — which is a NORMAL answer once a transfer settles
390	 * and drops off the list, so callers must resolve that against `domainInfo`
391	 * rather than treating it as a failure.
392	 *
393	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
394	 * (registrar.ts holds no state of its own).
395	 */
396	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
397	  if (SANDBOX) {
398	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
399	    const status =
400	      age < SANDBOX_APPROVAL_MS
401	        ? "pendingOwnerApproval"
402	        : age < SANDBOX_REGISTRY_MS
403	          ? "pendingRegistry"
404	          : "completed";
405	    return { domain, status, email: `owner@${domain}` };
406	  }
407	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
408	  if (!t) return null;
409	  return {
410	    domain: t.domainName ?? domain,
411	    status: String(t.status ?? "pending"),
412	    email: t.email ? String(t.email) : null,
413	  };
414	}
415	
416	/**
417	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
418	 * registrar refuses (e.g. the transfer already completed at the registry) —
419	 * callers must NOT credit the customer unless this resolves.
420	 */
421	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
422	  if (SANDBOX) return { domain, status: "cancelled", email: null };
423	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
424	  return {
425	    domain: t?.domainName ?? domain,
426	    status: String(t?.status ?? "cancelled"),
427	    email: t?.email ? String(t.email) : null,
428	  };
429	}
430	
431	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
432	export async function listTransfers(): Promise<TransferInfo[]> {
433	  if (SANDBOX) return [];
434	  const json = await nc("GET", "/v4/transfers");
435	  return (json.transfers ?? []).map((t: any) => ({
436	    domain: t.domainName,
437	    status: String(t.status ?? "pending"),
438	    email: t.email ? String(t.email) : null,
439	  }));
440	}
