442	/** Bucket a raw registrar transfer status into something we can act on. */
443	export function transferOutcome(status: string): "completed" | "failed" | "pending" {
444	  const s = status.toLowerCase();
445	  if (/(complete|success|transferred)/.test(s)) return "completed";
446	  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
447	  return "pending";
448	}
449	
450	/** Human label for a raw registrar transfer status. */
451	export function transferStatusLabel(status: string): string {
452	  const s = status.toLowerCase();
453	  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
454	  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
455	  if (/complete|success|transferred/.test(s)) return "Completed";
456	  if (/cancel/.test(s)) return "Cancelled";
457	  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
458	  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
459	  return status;
460	}
