1	import { NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { jsonError } from "@/lib/tools/api";
4	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
5	import {
6	  generateSuggestions,
7	  readIdea,
8	  readKeywords,
9	  readTlds,
10	  readTone,
11	  MIN_IDEA_LEN,
12	} from "@/lib/tools/domain-suggest";
13	
14	export const runtime = "nodejs";
15	export const dynamic = "force-dynamic";
16	
17	/**
18	 * AI domain-name generator — public, unauthenticated, and therefore capped hard.
19	 *
20	 * The brief → names → live availability pipeline lives in `lib/tools/domain-suggest.ts`
21	 * and is shared verbatim with the signed-in portal route. This handler owns only
22	 * the public surface's concerns:
23	 *
24	 *   1. Two per-IP sliding windows (burst + hourly), keyed on the PROXY-ATTESTED
25	 *      address via the shared `toolRateLimitByIp` helper — never the spoofable
26	 *      first hop of X-Forwarded-For. One accepted request = at most one Claude
27	 *      call and one batched registrar lookup.
28	 *   2. Input validation, so a too-short brief costs nothing.
29	 *
30	 * Degradation is handled inside the pipeline: no ANTHROPIC_API_KEY (or any Claude
31	 * failure) falls back to the local heuristic generator; a registrar failure marks
32	 * names "unknown" rather than claiming they're free. Neither surfaces as an error.
33	 */
34	
35	export async function POST(req: Request) {
36	  // Burst limit, then a longer window so a single IP can't grind all day.
37	  const burst = toolRateLimitByIp(req, "domain-generator", { max: 6, windowMs: 60_000 });
38	  if (burst) return burst;
39	  const hourly = toolRateLimitByIp(req, "domain-generator-hourly", { max: 40, windowMs: 60 * 60_000 });
40	  if (hourly) return hourly;
41	
42	  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
43	  const idea = readIdea(body.idea);
44	  const keywords = readKeywords(body.keywords);
45	  const tone = readTone(body.tone);
46	  const tlds = readTlds(body.tlds);
47	
48	  if (idea.length < MIN_IDEA_LEN) {
49	    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
50	  }
51	
52	  const data = await generateSuggestions({ idea, keywords, tone, tlds });
53	
54	  if (!data.results.length) {
55	    return jsonError("We couldn't build names from that description — try adding a little more detail.");
56	  }
57	
58	  // Signed-in visitors go straight into the pre-filled registration wizard;
59	  // everyone else lands on signup with the name carried through.
60	  let signedIn = false;
61	  try {
62	    signedIn = Boolean(await currentUser());
63	  } catch {
64	    /* session lookup unavailable — treat as anonymous */
65	  }
66	
67	  return NextResponse.json({ ok: true, signedIn, ...data });
68	}
