1	import { NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { jsonError } from "@/lib/tools/api";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import {
6	  generateSuggestions,
7	  readIdea,
8	  readKeywords,
9	  readTlds,
10	  readTone,
11	  MIN_IDEA_LEN,
12	} from "@/lib/tools/domain-suggest";
13	
14	export const runtime = "nodejs";
15	export const dynamic = "force-dynamic";
16	
17	/**
18	 * Domain-name generator for the signed-in customer portal.
19	 *
20	 * Same brief → names → live availability pipeline as the public marketing tool
21	 * (both call `generateSuggestions`), but this surface is authenticated, so:
22	 *
23	 *   - The caller must be signed in.
24	 *   - Throttling keys on the ACCOUNT (`user.id`), a real identity, not the
25	 *     shared, spoofable client IP. A logged-in customer gets a more generous
26	 *     budget than an anonymous visitor while the platform Claude key and the
27	 *     metered registrar stay protected. (The IP-keyed limiter would lump a whole
28	 *     office behind one NAT into a single bucket; the account key is the honest
29	 *     one here.)
30	 *
31	 * Every "Register" the UI renders points at /dashboard/domains/register?domain=…,
32	 * the existing purchase path, which re-checks availability and price before charge.
33	 */
34	
35	export async function POST(req: Request) {
36	  const user = await currentUser();
37	  if (!user) {
38	    return NextResponse.json({ ok: false, error: "Sign in to generate domain ideas." }, { status: 401 });
39	  }
40	
41	  // Burst then hourly, both keyed on the account. AI + registrar cost money even
42	  // for a paying customer, so the windows are generous but not unbounded.
43	  const burst = checkRateLimit(`tool:domain-generator:user:${user.id}`, { max: 12, windowMs: 60_000 });
44	  if (!burst.ok) {
45	    return NextResponse.json(
46	      { ok: false, error: `You're generating quickly — try again in ${burst.retryAfterSec}s.` },
47	      { status: 429, headers: { "Retry-After": String(burst.retryAfterSec) } },
48	    );
49	  }
50	  const hourly = checkRateLimit(`tool:domain-generator-hourly:user:${user.id}`, { max: 120, windowMs: 60 * 60_000 });
51	  if (!hourly.ok) {
52	    return NextResponse.json(
53	      { ok: false, error: `Hourly generation limit reached — try again in ${hourly.retryAfterSec}s.` },
54	      { status: 429, headers: { "Retry-After": String(hourly.retryAfterSec) } },
55	    );
56	  }
57	
58	  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
59	  const idea = readIdea(body.idea);
60	  const keywords = readKeywords(body.keywords);
61	  const tone = readTone(body.tone);
62	  const tlds = readTlds(body.tlds);
63	
64	  if (idea.length < MIN_IDEA_LEN) {
65	    return jsonError("Describe your business or idea in a few words (at least 8 characters).");
66	  }
67	
68	  const data = await generateSuggestions({ idea, keywords, tone, tlds });
69	
70	  if (!data.results.length) {
71	    return jsonError("We couldn't build names from that description — try adding a little more detail.");
72	  }
73	
74	  // Always signed in on this route — the UI links straight to the register wizard.
75	  return NextResponse.json({ ok: true, signedIn: true, ...data });
76	}
