import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { registrarConfigured } from "@/lib/registrar";
import { checkAvailabilityBatched, type DomainResult } from "@/lib/tools/domain-availability";
import { SEARCH_TLDS } from "@/components/marketing/tlds";
import { trustedClientIp } from "@/app/api/_lib/client-ip";

export const dynamic = "force-dynamic";

/**
 * Exact-domain search behind both the marketing DomainChecker and the signed-in
 * dashboard DomainSearch.
 *
 * The old handler had two money-losing defects, both fixed here:
 *
 *   1. It hardcoded a tiny extension list (com/net/io/dev…) and, for a full
 *      domain like `mahaskitchen.in`, only ever offered .com/.net/.io/.dev as
 *      alternatives — a registrable, available `.in` was never surfaced.
 *   2. It DROPPED every unavailable result (`filter(priceCents !== null)`), so a
 *      taken exact match simply vanished instead of being shown as "Taken".
 *
 * Now:
 *   - The EXACT typed domain (when the query is a full domain) is always checked
 *     and returned first as `exact`, whatever its TLD — the registrar prices
 *     arbitrary TLDs.
 *   - The base name is checked across a BROAD catalog (SEARCH_TLDS, ~two dozen),
 *     and taken / unknown results are RETURNED, clearly statused, not hidden.
 *   - Availability goes through the shared batched+cached+globally-throttled
 *     `checkAvailabilityBatched`, so the whole extension list is ONE upstream
 *     call to the metered registrar, and prices are only ever the real ones it
 *     returned.
 */

type CheckStatus = "available" | "taken" | "unknown";

type CheckItem = {
  domain: string;
  sld: string;
  tld: string;
  status: CheckStatus;
  /** Convenience mirror of `status === "available"` for older callers. */
  available: boolean;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
};

/** Cap so the base name + its extensions fit a SINGLE batched registrar call. */
const MAX_CANDIDATES = 24;

function splitDomain(domain: string): { sld: string; tld: string } {
  const dot = domain.indexOf(".");
  return dot > 0 ? { sld: domain.slice(0, dot), tld: domain.slice(dot + 1) } : { sld: domain, tld: "" };
}

function toItem(r: DomainResult): CheckItem {
  const { sld, tld } = splitDomain(r.domain);
  return {
    domain: r.domain,
    sld,
    tld,
    status: r.status,
    available: r.status === "available",
    premium: r.premium,
    priceCents: r.priceCents,
    renewCents: r.renewCents,
  };
}

const unknownItem = (domain: string): CheckItem => ({
  domain,
  ...splitDomain(domain),
  status: "unknown",
  available: false,
  premium: false,
  priceCents: null,
  renewCents: null,
});

export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  // One search fans out to the registrar (one batched upstream call) — throttle
  // per-IP so a customer can't grind the metered registrar.
  const rl = checkRateLimit(`domcheck:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
  if (q.length < 2) return NextResponse.json({ results: [] });
  if (!registrarConfigured()) {
    return NextResponse.json({ configured: false, results: [] });
  }

  // A query is a full domain when it has a dot with a non-empty label on each
  // side (the right side being a plausible TLD, 2+ chars). We keep the EXACT
  // string typed — including its TLD — and never silently drop it.
  const dot = q.indexOf(".");
  const base = dot > 0 ? q.slice(0, dot) : q;
  const typedTld = dot > 0 ? q.slice(dot + 1) : "";
  const exactDomain = dot > 0 && base.length >= 1 && typedTld.length >= 2 ? q : null;

  // Build the candidate list: the exact typed domain first (primary), then the
  // base name across the broad catalog, de-duplicated, capped to one batch.
  const seen = new Set<string>();
  const candidates: string[] = [];
  if (exactDomain) {
    candidates.push(exactDomain);
    seen.add(exactDomain);
  }
  if (base.length >= 1) {
    for (const tld of SEARCH_TLDS) {
      if (candidates.length >= MAX_CANDIDATES) break;
      const d = `${base}.${tld}`;
      if (seen.has(d)) continue;
      seen.add(d);
      candidates.push(d);
    }
  }
  if (candidates.length === 0) return NextResponse.json({ configured: true, results: [] });

  // ONE batched, cached, globally-throttled registrar lookup for the whole list.
  const outcome = await checkAvailabilityBatched(candidates);
  const byDomain = new Map(outcome.results.map((r) => [r.domain.toLowerCase(), r]));
  const itemFor = (d: string): CheckItem => {
    const r = byDomain.get(d.toLowerCase());
    return r ? toItem(r) : unknownItem(d);
  };

  const exact = exactDomain ? itemFor(exactDomain) : null;
  const results = candidates.filter((d) => d !== exactDomain).map(itemFor);

  return NextResponse.json({
    configured: outcome.configured,
    throttled: outcome.throttled,
    query: q,
    exact,
    results,
  });
}

"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { IconArrow, IconCheck } from "./icons";

type Status = "available" | "taken" | "unknown";

type Result = {
  domain: string;
  sld: string;
  tld: string;
  status: Status;
  available: boolean;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
};

type ApiResponse = {
  configured?: boolean;
  throttled?: boolean;
  query?: string;
  exact?: Result | null;
  results?: Result[];
};

type UiStatus = "idle" | "loading" | "results" | "soon" | "auth" | "error";

import { POPULAR_TLDS } from "./tlds";
export { POPULAR_TLDS };

function money(cents: number | null): string {
  if (cents == null) return "—";
  const v = cents / 100;
  return `$${v.toFixed(2)}`;
}

const transferHref = (domain: string) => `/dashboard/domains/transfer?domain=${encodeURIComponent(domain)}`;
const registerHref = (domain: string) => `/register?domain=${encodeURIComponent(domain)}`;

export function DomainChecker({ compact = false }: { compact?: boolean }) {
  const [q, setQ] = useState("");
  const [status, setStatus] = useState<UiStatus>("idle");
  const [exact, setExact] = useState<Result | null>(null);
  const [results, setResults] = useState<Result[]>([]);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abort = useRef<AbortController | null>(null);

  useEffect(() => {
    const query = q.trim().toLowerCase();
    if (debounce.current) clearTimeout(debounce.current);
    abort.current?.abort();

    if (query.length < 2) {
      setStatus("idle");
      setExact(null);
      setResults([]);
      return;
    }

    setStatus("loading");
    debounce.current = setTimeout(async () => {
      const ac = new AbortController();
      abort.current = ac;
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
          signal: ac.signal,
        });
        if (res.status === 401) {
          setStatus("auth");
          return;
        }
        const data: ApiResponse = await res.json();
        if (data.configured === false) {
          setStatus("soon");
          return;
        }
        setExact(data.exact ?? null);
        setResults(Array.isArray(data.results) ? data.results : []);
        setStatus("results");
      } catch (e: any) {
        if (e?.name === "AbortError") return;
        setStatus("error");
      }
    }, 400);

    return () => {
      if (debounce.current) clearTimeout(debounce.current);
    };
  }, [q]);

  // Alternatives: available first (cheapest first), then unknown, then taken.
  const rank: Record<Status, number> = { available: 0, unknown: 1, taken: 2 };
  const sorted = [...results].sort(
    (a, b) =>
      rank[a.status] - rank[b.status] ||
      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
      a.domain.length - b.domain.length,
  );
  const availableAlts = sorted.filter((r) => r.status === "available");

  return (
    <div className="w-full">
      <style>{`
        .nx-dom-row { animation: nx-dom-in 0.35s cubic-bezier(0.22,1,0.36,1) both; }
        @keyframes nx-dom-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .nx-dot { animation: nx-dot 1s ease-in-out infinite; }
        .nx-dot:nth-child(2) { animation-delay: 0.15s; }
        .nx-dot:nth-child(3) { animation-delay: 0.3s; }
        @keyframes nx-dot { 0%,100% { opacity: 0.25; } 50% { opacity: 1; } }
        @media (prefers-reduced-motion: reduce) { .nx-dom-row, .nx-dot { animation: none !important; } }
      `}</style>

      {/* Search field */}
      <div className="group relative">
        <div className="pointer-events-none absolute -inset-[1px] rounded-2xl bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-0 blur transition-opacity duration-300 group-focus-within:opacity-100" />
        <div className="relative flex items-center gap-2 rounded-2xl border border-white/10 bg-navy-900/80 p-2 backdrop-blur-md transition-colors focus-within:border-brand-400/50">
          <span className="pl-2 text-slate-500" aria-hidden>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="11" cy="11" r="7" />
              <path d="m20 20-3-3" />
            </svg>
          </span>
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Find your perfect domain — try mahaskitchen.in"
            spellCheck={false}
            autoCapitalize="off"
            autoCorrect="off"
            className="min-w-0 flex-1 bg-transparent px-1 py-2.5 text-base text-slate-100 outline-none placeholder:text-slate-500"
            aria-label="Search for a domain"
          />
          <span className="hidden shrink-0 items-center gap-2 pr-2 text-xs text-slate-500 sm:flex">
            {status === "loading" ? (
              <>
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
                <span className="nx-dot h-1.5 w-1.5 rounded-full bg-brand-400" />
              </>
            ) : (
              <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-1">
                Any extension
              </span>
            )}
          </span>
        </div>
      </div>

      {/* Results / states */}
      <div className="mt-4">
        {status === "results" && (
          <div className="space-y-4">
            {/* Exact typed domain — the primary result, whatever its extension */}
            {exact && (
              <div
                className={`nx-dom-row rounded-xl border p-4 backdrop-blur-md ${
                  exact.status === "available"
                    ? "border-emerald-500/25 bg-emerald-500/[0.05]"
                    : exact.status === "taken"
                      ? "border-white/10 bg-navy-900/70"
                      : "border-amber-400/25 bg-amber-400/[0.05]"
                }`}
              >
                <div className="flex flex-wrap items-center gap-3">
                  <span
                    className={`flex h-7 w-7 items-center justify-center rounded-full ${
                      exact.status === "available"
                        ? "bg-emerald-500/15 text-emerald-400"
                        : "bg-slate-500/15 text-slate-400"
                    }`}
                  >
                    {exact.status === "available" ? (
                      <IconCheck size={14} />
                    ) : (
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                        <path d="M6 6l12 12M18 6 6 18" />
                      </svg>
                    )}
                  </span>
                  <span className="min-w-0 break-all font-mono text-base font-semibold text-white">{exact.domain}</span>
                  {exact.premium && (
                    <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
                      Premium
                    </span>
                  )}
                  {exact.status === "available" ? (
                    <span className="ml-auto flex items-center gap-3">
                      <span className="text-right text-sm">
                        <span className="font-semibold text-white">{money(exact.priceCents)}</span>
                        <span className="text-slate-500">/yr</span>
                      </span>
                      <Link href={registerHref(exact.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
                        Register
                        <IconArrow size={13} />
                      </Link>
                    </span>
                  ) : exact.status === "taken" ? (
                    <span className="ml-auto rounded-full border border-white/10 bg-white/[0.05] px-2.5 py-1 text-xs font-medium text-slate-300">
                      Taken
                    </span>
                  ) : (
                    <span className="ml-auto text-xs text-amber-300/90">Couldn&apos;t verify</span>
                  )}
                </div>
                {exact.status === "taken" && (
                  <p className="mt-3 text-xs leading-relaxed text-slate-400">
                    <b className="text-slate-300">{exact.domain}</b> is already registered.{" "}
                    <Link href={transferHref(exact.domain)} className="text-brand-300 hover:text-brand-200">
                      Transfer it in
                    </Link>{" "}
                    if it&apos;s yours, or pick one of the available extensions below.
                  </p>
                )}
              </div>
            )}

            {/* Alternative extensions */}
            {sorted.length > 0 && (
              <div>
                {exact && (
                  <p className="mb-2 text-xs font-medium uppercase tracking-wider text-slate-500">
                    {exact.status === "available" ? "More extensions" : "Available alternatives"}
                  </p>
                )}
                <ul className="space-y-2">
                  {sorted.map((r, i) => (
                    <li
                      key={r.domain}
                      className="nx-dom-row flex flex-wrap items-center gap-3 rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 backdrop-blur-md transition-colors hover:border-brand-500/30"
                      style={{ animationDelay: `${Math.min(i, 10) * 35}ms` }}
                    >
                      <span
                        className={`flex h-7 w-7 items-center justify-center rounded-full ${
                          r.status === "available" ? "bg-emerald-500/15 text-emerald-400" : "bg-slate-500/15 text-slate-500"
                        }`}
                      >
                        {r.status === "available" ? (
                          <IconCheck size={14} />
                        ) : (
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                            <path d="M6 6l12 12M18 6 6 18" />
                          </svg>
                        )}
                      </span>
                      <span className="font-mono text-sm font-medium text-white">{r.domain}</span>
                      {r.premium && (
                        <span className="rounded-full border border-amber-400/30 bg-amber-400/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-amber-300">
                          Premium
                        </span>
                      )}
                      <span className="ml-auto flex items-center gap-3">
                        {r.status === "available" ? (
                          <>
                            <span className="text-right text-sm">
                              <span className="font-semibold text-white">{money(r.priceCents)}</span>
                              <span className="text-slate-500">/yr</span>
                            </span>
                            <Link href={registerHref(r.domain)} className="btn-primary px-3.5 py-1.5 text-xs">
                              Register
                              <IconArrow size={13} />
                            </Link>
                          </>
                        ) : r.status === "taken" ? (
                          <span className="text-xs text-slate-500">Taken</span>
                        ) : (
                          <span className="text-xs text-amber-300/80">Couldn&apos;t verify</span>
                        )}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {!exact && availableAlts.length === 0 && sorted.length > 0 && (
              <p className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-400">
                Every extension for that name is taken — try a different name.
              </p>
            )}

            {!exact && sorted.length === 0 && (
              <p className="rounded-xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 text-sm text-slate-400">
                No matches for that query — try a different name.
              </p>
            )}
          </div>
        )}

        {status === "auth" && (
          <div className="rounded-xl border border-brand-500/25 bg-brand-500/[0.06] px-4 py-3 text-sm text-slate-300">
            <b className="text-white">Live availability is one step away.</b>{" "}
            <Link href="/register" className="text-brand-300 hover:underline">
              Create a free account
            </Link>{" "}
            to search and register domains in real time — then point them at your VPS in a click.
          </div>
        )}

        {status === "soon" && (
          <div className="rounded-xl border border-amber-400/25 bg-amber-400/[0.06] px-4 py-3 text-sm text-amber-200/90">
            <b>Domain registration is launching soon.</b> Prices below are indicative starting
            rates — check back shortly to register live.
          </div>
        )}

        {status === "error" && (
          <p className="rounded-xl border border-red-500/25 bg-red-500/[0.06] px-4 py-3 text-sm text-red-300">
            Something went wrong checking that domain. Please try again.
          </p>
        )}
      </div>

      {/* Popular TLD chips */}
      {!compact && (
        <div className="mt-6">
          <p className="mb-3 text-xs font-medium uppercase tracking-wider text-slate-500">
            Popular extensions · from
          </p>
          <div className="flex flex-wrap gap-2">
            {POPULAR_TLDS.map((t) => (
              <span
                key={t.tld}
                className="inline-flex items-center gap-2 rounded-lg border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-sm text-slate-300 transition-colors hover:border-brand-500/30 hover:text-white"
              >
                <span className="font-mono font-semibold text-brand-300">{t.tld}</span>
                <span className="text-xs text-slate-500">{money(t.fromCents)}</span>
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { fmtMoney } from "@/components/ui/primitives";

type Status = "available" | "taken" | "unknown";

export type DomainCheckResult = {
  domain: string;
  sld: string;
  tld: string;
  status: Status;
  available: boolean;
  premium: boolean;
  priceCents: number | null;
  renewCents: number | null;
};

type ApiResponse = {
  configured?: boolean;
  throttled?: boolean;
  query?: string;
  exact?: DomainCheckResult | null;
  results?: DomainCheckResult[];
  error?: string;
};

const POPULAR_TLDS = [".com", ".net", ".org", ".io", ".co", ".shop", ".in", ".ai"];

const registerHref = (domain: string) => `/dashboard/domains/register?domain=${encodeURIComponent(domain)}`;
const transferHref = (domain: string) => `/dashboard/domains/transfer?domain=${encodeURIComponent(domain)}`;

export function DomainSearch({ configured }: { configured: boolean }) {
  const [q, setQ] = useState("");
  const [exact, setExact] = useState<DomainCheckResult | null>(null);
  const [results, setResults] = useState<DomainCheckResult[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!configured) return;
    if (timer.current) clearTimeout(timer.current);
    const query = q.trim().toLowerCase();
    if (query.length < 2) {
      setExact(null);
      setResults(null);
      setLoading(false);
      setError(null);
      return;
    }
    setLoading(true);
    timer.current = setTimeout(async () => {
      try {
        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, {
          cache: "no-store",
        });
        const json: ApiResponse = await res.json();
        setError(json.error ?? null);
        setExact(json.exact ?? null);
        setResults(Array.isArray(json.results) ? json.results : []);
      } catch {
        setError("Search failed — try again.");
        setExact(null);
        setResults([]);
      }
      setLoading(false);
    }, 400);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [q, configured]);

  // Available first (cheapest first), then unknown, then taken.
  const rank: Record<Status, number> = { available: 0, unknown: 1, taken: 2 };
  const sorted = [...(results ?? [])].sort(
    (a, b) =>
      rank[a.status] - rank[b.status] ||
      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
      a.domain.length - b.domain.length,
  );

  function priceCell(r: DomainCheckResult) {
    if (r.premium) {
      return (
        <span className="flex items-center gap-3">
          <span className="rounded-full border border-amber-500/40 bg-amber-500/10 px-2 py-0.5 text-[10px] font-semibold text-amber-300">
            premium
          </span>
          <span className="text-xs text-slate-500">not supported</span>
        </span>
      );
    }
    if (r.status === "available" && r.priceCents !== null) {
      return (
        <span className="flex items-center gap-3">
          <span className="text-right text-sm font-semibold text-emerald-400">
            {fmtMoney(r.priceCents)}
            <span className="text-xs font-normal text-slate-400">/yr</span>
          </span>
          <Link href={registerHref(r.domain)} className="btn-primary px-3 py-1 text-xs">
            Register →
          </Link>
        </span>
      );
    }
    if (r.status === "unknown") {
      return (
        <span className="rounded-full border border-amber-400/20 bg-amber-400/[0.06] px-2 py-0.5 text-xs text-amber-300/80">
          couldn&apos;t verify
        </span>
      );
    }
    return (
      <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-xs text-slate-500">
        taken
      </span>
    );
  }

  const dot = (r: DomainCheckResult) =>
    r.status === "available" && !r.premium ? "bg-emerald-400" : r.premium ? "bg-amber-400" : "bg-slate-600";

  return (
    <div className="card relative overflow-hidden bg-gradient-to-br from-navy-900/90 to-navy-850/70">
      <style>{`
        @keyframes domainResultIn {
          from { opacity: 0; transform: translateY(6px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
      <div className="glow-brand pointer-events-none absolute -right-24 -top-24 h-56 w-56 rounded-full bg-brand-500/20 blur-3xl" />

      <div className="relative">
        <div className="flex items-center gap-2">
          <span className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-accent-blue/25 to-brand-500/25 text-brand-200">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
              <circle cx="12" cy="12" r="9" />
              <path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18" />
            </svg>
          </span>
          <div>
            <h2 className="text-lg font-semibold leading-tight">
              Find your <span className="grad-text">perfect domain</span>
            </h2>
            <p className="text-sm text-slate-400">
              Type any name or a full domain like <span className="font-mono">mahaskitchen.in</span> — we check that exact
              extension plus ~two dozen more, live.
            </p>
          </div>
        </div>

        <div className="relative mt-4 max-w-xl">
          <input
            className="input py-3 pr-11 text-base"
            placeholder={configured ? "mahaskitchen.in" : "Domain search unavailable"}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            disabled={!configured}
            autoComplete="off"
            spellCheck={false}
          />
          <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500">
            {loading ? (
              <span className="block h-4 w-4 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
            ) : (
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="11" cy="11" r="7" />
                <path d="m20 20-3.5-3.5" />
              </svg>
            )}
          </span>
        </div>

        {configured && results === null && !loading && (
          <div className="mt-3 flex flex-wrap items-center gap-2">
            <span className="text-xs text-slate-500">Popular:</span>
            {POPULAR_TLDS.map((t) => (
              <span
                key={t}
                className="rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-0.5 font-mono text-xs text-slate-400"
              >
                {t}
              </span>
            ))}
          </div>
        )}

        {!configured && (
          <div className="mt-4 max-w-xl rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
            Domain registration activates once the registrar integration is configured. You can still
            manage domains already on your account.
          </div>
        )}

        {error && <p className="mt-3 text-sm text-red-400">{error}</p>}

        {/* Exact typed domain — always shown first, whatever its extension */}
        {exact && !loading && (
          <div
            className={`mt-4 max-w-xl rounded-xl border px-4 py-3 ${
              exact.status === "available"
                ? "border-emerald-500/25 bg-emerald-500/[0.05]"
                : exact.status === "taken"
                  ? "border-white/10 bg-navy-900/70"
                  : "border-amber-400/25 bg-amber-400/[0.05]"
            }`}
          >
            <div className="flex items-center justify-between gap-3">
              <span className="flex items-center gap-2 font-mono text-sm">
                <span className={`h-1.5 w-1.5 rounded-full ${dot(exact)}`} />
                {exact.domain}
              </span>
              {priceCell(exact)}
            </div>
            {exact.status === "taken" && (
              <p className="mt-2 text-xs leading-relaxed text-slate-400">
                Already registered.{" "}
                <Link href={transferHref(exact.domain)} className="text-brand-300 hover:text-brand-200">
                  Transfer it in
                </Link>{" "}
                if it&apos;s yours, or pick an available extension below.
              </p>
            )}
          </div>
        )}

        {results !== null && !loading && (
          <>
            {exact && sorted.length > 0 && (
              <p className="mt-4 max-w-xl text-xs font-medium uppercase tracking-wider text-slate-500">
                {exact.status === "available" ? "More extensions" : "Other extensions"}
              </p>
            )}
            <ul className="mt-2 max-w-xl divide-y divide-white/[0.05] overflow-hidden rounded-xl border border-white/[0.06] bg-navy-900/60">
              {sorted.length === 0 && !exact && !error && (
                <li className="px-4 py-3 text-sm text-slate-400">No extensions matched that search.</li>
              )}
              {sorted.map((r, i) => (
                <li
                  key={r.domain}
                  className="flex items-center justify-between gap-3 px-4 py-3"
                  style={{ animation: `domainResultIn 0.28s ease both`, animationDelay: `${Math.min(i, 12) * 40}ms` }}
                >
                  <span className="flex items-center gap-2 font-mono text-sm">
                    <span className={`h-1.5 w-1.5 rounded-full ${dot(r)}`} />
                    {r.domain}
                  </span>
                  {priceCell(r)}
                </li>
              ))}
            </ul>
          </>
        )}
      </div>
    </div>
  );
}

