// Live availability + price for the pre-selected domain (best-effort). Mapped
// into the shared DomainCheckResult shape (status + sld/tld) the wizard uses.
let initialCheck: DomainCheckResult | null = null;
if (valid) {
  try {
    const [check] = await checkDomains([domain]);
    if (check) {
      const dot = check.domain.indexOf(".");
      const available = check.available && check.priceCents !== null;
      initialCheck = {
        domain: check.domain,
        sld: dot > 0 ? check.domain.slice(0, dot) : check.domain,
        tld: dot > 0 ? check.domain.slice(dot + 1) : "",
        status: available ? "available" : "taken",
        available,
        premium: check.premium,
        priceCents: available ? check.priceCents : null,
        renewCents: available ? check.renewCents : null,
      };
    }
  } catch {
    /* registrar briefly unreachable — the wizard can re-check client-side */
  }
}
